/* From Uiverse.io by Gaurav-WebDev - Tags: card, hover effect, cool card */
.__UIV_SCOPE__ .card {
  width: 190px;
  height: 254px;
  background: lightgray;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2em;
  color: #333;
  font-family: 'Gill Sans', 'Gill Sans MT', Calibri, 'Trebuchet MS', sans-serif;
  border-radius: 40px;
  cursor: pointer;
  position: relative;
  transition: all 0.7s ease-in-out;
  overflow: hidden;
}

.__UIV_SCOPE__ .card::before {
  content: "";
  position: absolute;
  height: 40%;
  width: 100%;
  background-color: #088080;
  bottom: 0;
  right: 0;
  transform: translatey(70px);
  border-radius: 100%;
  transition: all 0.7s ease-in-out;
}

.__UIV_SCOPE__ .c-txt {
  z-index: 2;
}

.__UIV_SCOPE__ .card:hover::before {
  transform: scale(7) translate(-20px);
}

.__UIV_SCOPE__ .card:hover {
  box-shadow: 1px -10px 500px 500px #9fe4e44a;
  color: #f3f3f3;
}
